    let __start = tbpTrajectory.starttbpTrajectory(&fbb)
    tbpTrajectory.add(DIMENSIONAL: DIMENSIONAL, &fbb)
    tbpTrajectory.add(FRAME: FRAME, &fbb)
    tbpTrajectory.add(EPOCH_MS: EPOCH_MS, &fbb)
    tbpTrajectory.addVectorOf(TIMES: TIMES, &fbb)
    tbpTrajectory.addVectorOf(STATES: STATES, &fbb)
    tbpTrajectory.addVectorOf(STATE_TRANSITION: STATE_TRANSITION, &fbb)
    tbpTrajectory.add(JACOBI: JACOBI, &fbb)
    return tbpTrajectory.endtbpTrajectory(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DIMENSIONAL, fieldName: "DIMENSIONAL", required: false, type: Bool.self)
    try _v.visit(field: VT.FRAME, fieldName: "FRAME", required: false, type: ForwardOffset<RFM>.self)
    try _v.visit(field: VT.EPOCH_MS, fieldName: "EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.TIMES, fieldName: "TIMES", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STATES, fieldName: "STATES", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STATE_TRANSITION, fieldName: "STATE_TRANSITION", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.JACOBI, fieldName: "JACOBI", required: false, type: Double.self)
