    _ fbb: inout FlatBufferBuilder,
    KIND: tbpTransferKind = .unspecified,
    PARKING_ALTITUDE_KM: Double = 0.0,
    TARGET_ALTITUDE_KM: Double = 0.0,
    INCLINATION_DEG: Double = 0.0,
    TARGET_ORBITOffset TARGET_ORBIT: Offset = Offset(),
    MAX_ITERATIONS: UInt32 = 0,
    TOLERANCE: Double = 0.0,
    CONVERGED: Bool = false,
    BURNSVectorOffset BURNS: Offset = Offset(),
    TOTAL_DELTA_V_KM_S: Double = 0.0,
