    try _v.visit(field: VT.INCLINATION_DEG, fieldName: "INCLINATION_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.TARGET_ORBIT, fieldName: "TARGET_ORBIT", required: false, type: ForwardOffset<tbpPeriodicOrbit>.self)
    try _v.visit(field: VT.MAX_ITERATIONS, fieldName: "MAX_ITERATIONS", required: false, type: UInt32.self)
    try _v.visit(field: VT.TOLERANCE, fieldName: "TOLERANCE", required: false, type: Double.self)
    try _v.visit(field: VT.CONVERGED, fieldName: "CONVERGED", required: false, type: Bool.self)
    try _v.visit(field: VT.BURNS, fieldName: "BURNS", required: false, type: ForwardOffset<Vector<ForwardOffset<mplBurn>, mplBurn>>.self)
    try _v.visit(field: VT.TOTAL_DELTA_V_KM_S, fieldName: "TOTAL_DELTA_V_KM_S", required: false, type: Double.self)
    try _v.visit(field: VT.TIME_OF_FLIGHT_S, fieldName: "TIME_OF_FLIGHT_S", required: false, type: Double.self)
